class FAQManager{constructor(){this.container=document.getElementById('faq-items-container');this.totalFormsInput=document.getElementById('id_faqs-TOTAL_FORMS');this.emptyState=document.getElementById('faq-empty-state');this.counterEl=document.getElementById('faq-counter');if (!this.container||!this.totalFormsInput)return;this.init();}init(){this.attachAddHandler();this.attachItemHandlers();this.updateState();}attachAddHandler(){const addBtn=document.getElementById('faq-add-btn');if (addBtn){addBtn.addEventListener('click',(e)=>{e.preventDefault();this.addFAQ();});}const bulkImportBtn=document.getElementById('faq-bulk-import-btn');if (bulkImportBtn){bulkImportBtn.addEventListener('click',(e)=>{e.preventDefault();this.openBulkImportModal();});}}addFAQ(){const totalForms=parseInt(this.totalFormsInput.value);const newIndex=totalForms;this.container.querySelectorAll('.faq-item:not(.faq-item--deleted)').forEach(item=>{this.toggleAnswer(item,false);});const item=this.createFAQItem(newIndex);this.container.appendChild(item);this.totalFormsInput.value=newIndex+1;requestAnimationFrame(()=>{item.classList.add('faq-item--visible');});this.attachItemHandlers();this.updateState();this.updateSortOrders();this.toggleAnswer(item,true);const questionInput=item.querySelector('input[name$="-question"]');if (questionInput){setTimeout(()=>questionInput.focus(),150);}}createFAQItem(index){const item=document.createElement('div');item.className='faq-item';item.setAttribute('data-faq-index',index);item.innerHTML=`<div class="faq-item__header"><span class="faq-item__drag-handle" title="اسحب لإعادة الترتيب"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="6" r="1.5"/><circle cx="15" cy="6" r="1.5"/><circle cx="9" cy="12" r="1.5"/><circle cx="15" cy="12" r="1.5"/><circle cx="9" cy="18" r="1.5"/><circle cx="15" cy="18" r="1.5"/></svg></span><div class="faq-item__number">${index+1}</div><span class="faq-item__question-preview">سؤال جديد</span><button type="button" class="faq-item__toggle" title="عرض/إخفاء الإجابة" data-toggle-answer><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"></polyline></svg></button><button type="button" class="faq-item__delete" title="حذف السؤال"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M8 6V4a2 2 0 012-2h4a2 2 0 012 2v2m3 0v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6h14"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg></button></div><div class="faq-item__content"><div class="faq-item__field"><label for="id_faqs-${index}-question">السؤال</label><input type="text"
name="faqs-${index}-question"
id="id_faqs-${index}-question"
class="faq-item__question-input"
placeholder="السؤال"
dir="rtl"
required></div><div class="faq-item__field"><label for="id_faqs-${index}-answer">الإجابة</label><textarea name="faqs-${index}-answer"
id="id_faqs-${index}-answer"
class="faq-item__answer-input"
placeholder="الإجابة"
rows="4"
dir="rtl"
required></textarea></div><input type="hidden" name="faqs-${index}-sort_order" value="${index}"><input type="hidden" name="faqs-${index}-id" value=""><input type="hidden" name="faqs-${index}-DELETE" value=""></div>`;return item;}deleteFAQ(item){const deleteInput=item.querySelector('input[name$="-DELETE"]');const idInput=item.querySelector('input[name$="-id"]');if (idInput&&idInput.value){deleteInput.value='on';item.classList.add('faq-item--deleted');setTimeout(()=>{item.style.display='none';this.updateState();this.updateNumbers();},300);}else{item.classList.add('faq-item--deleted');setTimeout(()=>{item.remove();this.reindexForms();this.updateState();},300);}}toggleAnswer(item,forceExpand=null){const content=item.querySelector('.faq-item__content');const toggleBtn=item.querySelector('[data-toggle-answer]');const icon=toggleBtn.querySelector('svg');const isExpanded=content.classList.contains('expanded');const shouldExpand=forceExpand!==null?forceExpand:!isExpanded;if (shouldExpand){content.classList.add('expanded');icon.classList.add('rotated');toggleBtn.setAttribute('aria-expanded','true');}else{content.classList.remove('expanded');icon.classList.remove('rotated');toggleBtn.setAttribute('aria-expanded','false');}}updateQuestionPreview(item){const questionInput=item.querySelector('input[name$="-question"]');const preview=item.querySelector('.faq-item__question-preview');if (questionInput&&preview){const value=questionInput.value.trim();preview.textContent=value||'سؤال جديد';}}reindexForms(){const allItems=this.container.querySelectorAll('.faq-item');allItems.forEach((item,idx)=>{item.setAttribute('data-faq-index',idx);const inputs=item.querySelectorAll('input,textarea');inputs.forEach(input=>{const name=input.getAttribute('name');if (name){input.setAttribute('name',name.replace(/faqs-\d+-/,`faqs-${idx}-`));}const id=input.getAttribute('id');if (id){input.setAttribute('id',id.replace(/id_faqs-\d+-/,`id_faqs-${idx}-`));}});const labels=item.querySelectorAll('label');labels.forEach(label=>{const htmlFor=label.getAttribute('for');if (htmlFor){label.setAttribute('for',htmlFor.replace(/id_faqs-\d+-/,`id_faqs-${idx}-`));}});});this.totalFormsInput.value=allItems.length;this.updateNumbers();}updateNumbers(){const visibleItems=this.container.querySelectorAll('.faq-item:not(.faq-item--deleted):not([style*="display:none"])');visibleItems.forEach((item,idx)=>{const numberEl=item.querySelector('.faq-item__number');if (numberEl)numberEl.textContent=idx+1;});}updateSortOrders(){const visibleItems=this.container.querySelectorAll('.faq-item:not(.faq-item--deleted):not([style*="display:none"])');visibleItems.forEach((item,idx)=>{const sortInput=item.querySelector('input[name$="-sort_order"]');if (sortInput)sortInput.value=idx;});}updateState(){const visibleItems=this.container.querySelectorAll('.faq-item:not(.faq-item--deleted):not([style*="display:none"])');const count=visibleItems.length;if (this.emptyState){this.emptyState.style.display=count===0?'flex':'none';}if (this.counterEl){this.counterEl.textContent=count;this.counterEl.style.display=count>0?'inline-flex':'none';}}attachItemHandlers(){this.container.querySelectorAll('.faq-item__delete').forEach(btn=>{btn.onclick=(e)=>{e.preventDefault();const item=btn.closest('.faq-item');this.deleteFAQ(item);};});this.container.querySelectorAll('[data-toggle-answer]').forEach(btn=>{btn.onclick=(e)=>{e.preventDefault();const item=btn.closest('.faq-item');this.toggleAnswer(item);};});this.container.querySelectorAll('.faq-item__header').forEach(header=>{header.onclick=(e)=>{if (e.target.closest('.faq-item__delete')||e.target.closest('.faq-item__toggle')||e.target.closest('.faq-item__drag-handle')){return;}e.preventDefault();const item=header.closest('.faq-item');this.toggleAnswer(item);};});this.container.querySelectorAll('input[name$="-question"]').forEach(input=>{input.addEventListener('input',(e)=>{const item=e.target.closest('.faq-item');this.updateQuestionPreview(item);});});this.container.querySelectorAll('.faq-item').forEach(item=>{item.setAttribute('draggable','true');item.ondragstart=(e)=>this.onDragStart(e,item);item.ondragend=(e)=>this.onDragEnd(e,item);item.ondragover=(e)=>this.onDragOver(e,item);item.ondrop=(e)=>this.onDrop(e,item);});}onDragStart(e,item){item.classList.add('faq-item--dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','');}onDragEnd(e,item){item.classList.remove('faq-item--dragging');this.container.querySelectorAll('.faq-item--drag-over').forEach(el=>{el.classList.remove('faq-item--drag-over');});this.updateSortOrders();this.reindexForms();}onDragOver(e,item){e.preventDefault();e.dataTransfer.dropEffect='move';this.container.querySelectorAll('.faq-item--drag-over').forEach(el=>{el.classList.remove('faq-item--drag-over');});if (!item.classList.contains('faq-item--dragging')){item.classList.add('faq-item--drag-over');}}onDrop(e,item){e.preventDefault();item.classList.remove('faq-item--drag-over');const draggedItem=this.container.querySelector('.faq-item--dragging');if (draggedItem&&draggedItem!==item){const allItems=[...this.container.querySelectorAll('.faq-item:not([style*="display:none"])')];const draggedIdx=allItems.indexOf(draggedItem);const targetIdx=allItems.indexOf(item);if (draggedIdx<targetIdx){item.after(draggedItem);}else{item.before(draggedItem);}}}openBulkImportModal(){if (!this.bulkImportModal){this.createBulkImportModal();}this.bulkImportModal.classList.add('faq-bulk-import-modal--active');this.bulkImportModal.querySelector('.faq-bulk-import-textarea').focus();}createBulkImportModal(){const modal=document.createElement('div');modal.className='faq-bulk-import-modal';modal.id='faq-bulk-import-modal';modal.innerHTML=`<div class="faq-bulk-import-modal__overlay"></div><div class="faq-bulk-import-modal__content"><div class="faq-bulk-import-modal__header"><h3>استيراد أسئلة من Elementor</h3><button type="button" class="faq-bulk-import-modal__close" aria-label="إغلاق"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg></button></div><div class="faq-bulk-import-modal__body"><!--خطوة 1:إدخال الكود--><div class="faq-bulk-import-step faq-bulk-import-step--active" data-step="input"><div class="faq-bulk-import-step__content"><p class="faq-bulk-import-instructions">الصق كود HTML من Elementor Accordion(انسخ الكود من المنتور مباشرة)</p><textarea
class="faq-bulk-import-textarea"
placeholder="الصق كود Elementor Accordion هنا..."
dir="rtl"
spellcheck="false"></textarea><div class="faq-bulk-import-info"><p>💡<strong>كيفية الاستخدام:</strong></p><ul><li>افتح صفحة المنتور التي تحتوي على Accordion</li><li>افتح أدوات المتصفح(F12)</li><li>انسخ كود الـ Accordion كاملاً</li><li>الصقه هنا واضغط "التالي"</li></ul></div></div></div><!--خطوة 2:المعاينة والتحقق--><div class="faq-bulk-import-step" data-step="preview"><div class="faq-bulk-import-step__content"><div class="faq-bulk-import-preview"><div class="faq-bulk-import-preview__stats"><div class="faq-bulk-import-stat"><span class="faq-bulk-import-stat__label">عدد الأسئلة:</span><span class="faq-bulk-import-stat__value" data-faqs="0">0</span></div></div><div class="faq-bulk-import-preview__list"><div class="faq-bulk-import-preview__title">الأسئلة المكتشفة:</div><ul class="faq-bulk-import-preview__items"><!--سيتم ملؤها ديناميكياً--></ul></div><div class="faq-bulk-import-warnings" style="display:none;"><!--سيتم عرض التحذيرات هنا--></div></div></div></div></div><div class="faq-bulk-import-modal__footer"><button type="button" class="faq-bulk-import-btn-cancel">إلغاء</button><button type="button" class="faq-bulk-import-btn-next" data-step="input">التالي</button><button type="button" class="faq-bulk-import-btn-confirm" style="display:none;">تأكيد الاستيراد</button></div></div>`;document.body.appendChild(modal);this.bulkImportModal=modal;this.setupBulkImportEvents();}setupBulkImportEvents(){const overlay=this.bulkImportModal.querySelector('.faq-bulk-import-modal__overlay');const closeBtn=this.bulkImportModal.querySelector('.faq-bulk-import-modal__close');const cancelBtn=this.bulkImportModal.querySelector('.faq-bulk-import-btn-cancel');const nextBtn=this.bulkImportModal.querySelector('.faq-bulk-import-btn-next');const confirmBtn=this.bulkImportModal.querySelector('.faq-bulk-import-btn-confirm');const textarea=this.bulkImportModal.querySelector('.faq-bulk-import-textarea');const closeModal=()=>this.closeBulkImportModal();overlay.addEventListener('click',closeModal);closeBtn.addEventListener('click',closeModal);cancelBtn.addEventListener('click',closeModal);nextBtn.addEventListener('click',()=>this.goToBulkImportPreview());confirmBtn.addEventListener('click',()=>this.confirmBulkImport());textarea.addEventListener('input',()=>this.updateBulkImportPreview());}closeBulkImportModal(){this.bulkImportModal.classList.remove('faq-bulk-import-modal--active');this.resetBulkImportModal();}resetBulkImportModal(){this.bulkImportModal.querySelector('.faq-bulk-import-textarea').value='';this.showBulkImportStep('input');this.bulkImportModal.querySelector('.faq-bulk-import-btn-next').style.display='block';this.bulkImportModal.querySelector('.faq-bulk-import-btn-confirm').style.display='none';}showBulkImportStep(stepName){this.bulkImportModal.querySelectorAll('.faq-bulk-import-step').forEach(step=>{step.classList.remove('faq-bulk-import-step--active');});this.bulkImportModal.querySelector(`[data-step="${stepName}"]`).classList.add('faq-bulk-import-step--active');}parseElementorAccordion(htmlString){try{const cleanHtml=htmlString.trim();const parser=new DOMParser();const doc=parser.parseFromString(cleanHtml,'text/html');const accordion=doc.querySelector('.elementor-accordion');if (!accordion){return{faqs:[],errors:['لم يتم العثور على Elementor Accordion في الكود']};}const faqs=[];const errors=[];accordion.querySelectorAll('.elementor-accordion-item').forEach((item,itemIndex)=>{try{const titleEl=item.querySelector('.elementor-accordion-title');const question=titleEl?titleEl.textContent.trim():`سؤال بدون نص ${itemIndex+1}`;if (!question){errors.push(`السؤال ${itemIndex+1}:لم يتم العثور على نص`);return;}const contentEl=item.querySelector('.elementor-tab-content');const answer=contentEl?contentEl.textContent.trim():'';if (!answer){errors.push(`السؤال "${question}":لم يتم العثور على إجابة`);return;}faqs.push({question,answer});}catch(e){errors.push(`خطأ في معالجة السؤال ${itemIndex+1}:${e.message}`);}});if (faqs.length===0){return{faqs:[],errors:['لم يتم العثور على أي أسئلة في الكود']};}return{faqs,errors};}catch(e){return{faqs:[],errors:[`خطأ في تحليل الكود:${e.message}`]};}}updateBulkImportPreview(){const textarea=this.bulkImportModal.querySelector('.faq-bulk-import-textarea');const{faqs,errors}=this.parseElementorAccordion(textarea.value);this.bulkImportData={faqs,errors};this.bulkImportModal.querySelector('[data-faqs]').textContent=faqs.length;const itemsList=this.bulkImportModal.querySelector('.faq-bulk-import-preview__items');itemsList.innerHTML=faqs.map(faq=>`<li class="faq-bulk-import-preview__item"><span class="faq-bulk-import-preview__item-question">${this.escapeHtml(faq.question)}</span></li>`).join('');const warningsDiv=this.bulkImportModal.querySelector('.faq-bulk-import-warnings');if (errors.length>0){warningsDiv.innerHTML=`<div class="faq-bulk-import-warning"><div class="faq-bulk-import-warning__title">⚠️ تحذيرات:</div><ul class="faq-bulk-import-warning__list">${errors.map(error=>`<li>${error}</li>`).join('')}</ul></div>`;warningsDiv.style.display='block';}else{warningsDiv.style.display='none';}const nextBtn=this.bulkImportModal.querySelector('.faq-bulk-import-btn-next');nextBtn.disabled=faqs.length===0||errors.length>0;}goToBulkImportPreview(){this.updateBulkImportPreview();this.showBulkImportStep('preview');this.bulkImportModal.querySelector('.faq-bulk-import-btn-next').style.display='none';this.bulkImportModal.querySelector('.faq-bulk-import-btn-confirm').style.display='block';}confirmBulkImport(){if (!this.bulkImportData||this.bulkImportData.faqs.length===0){alert('لا توجد بيانات صحيحة للاستيراد');return;}this.bulkImportData.faqs.forEach(faq=>{this.importFAQ(faq);});this.closeBulkImportModal();this.showBulkImportSuccess(`تم استيراد ${this.bulkImportData.faqs.length}سؤال بنجاح`);}importFAQ(faq){this.addFAQ();const allItems=this.container.querySelectorAll('.faq-item');const newFAQItem=allItems[allItems.length-1];const questionInput=newFAQItem.querySelector('input[name$="-question"]');const answerInput=newFAQItem.querySelector('textarea[name$="-answer"]');if (questionInput){questionInput.value=faq.question;this.updateQuestionPreview(newFAQItem);}if (answerInput){answerInput.value=faq.answer;}}showBulkImportSuccess(message){const messageDiv=document.createElement('div');messageDiv.className='faq-bulk-import-success-message';messageDiv.innerHTML=`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"></polyline></svg><span>${message}</span>`;document.body.appendChild(messageDiv);setTimeout(()=>{messageDiv.classList.add('faq-bulk-import-success-message--hide');setTimeout(()=>messageDiv.remove(),300);},3000);}escapeHtml(text){const div=document.createElement('div');div.textContent=text;return div.innerHTML;}}document.addEventListener('DOMContentLoaded',()=>{window.faqManager=new FAQManager();});